mapper.select:
SELECT ds.*, ll.lian_lu_name AS lianLuName, gl.guan_lang_name AS guanLangName
FROM t_zgsq_ding_shi ds
LEFT JOIN t_zgsq_lian_lu ll ON ds.lian_lu_id = ll.lian_lu_id AND ll.deleted = 0
LEFT JOIN t_zgsq_guan_lang gl ON ds.guan_lang_id = gl.guan_lang_id AND gl.deleted = 0
WHERE 1 = 1

    AND ds.ding_shi_name LIKE CONCAT('%', #{dingShiName}, '%')


    AND ds.ding_shi_status = #{dingShiStatus}


    AND ds.lian_lu_id = #{lianLuId}


    AND ds.guan_lang_id = #{guanLangId}

ORDER BY ds.ding_shi_id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM t_zgsq_ding_shi ds
WHERE 1 = 1

    AND ds.ding_shi_name LIKE CONCAT('%', #{dingShiName}, '%')


    AND ds.ding_shi_status = #{dingShiStatus}


    AND ds.lian_lu_id = #{lianLuId}


    AND ds.guan_lang_id = #{guanLangId}
